    '''
    Use the filename variable to open a file, 
    load its contents into a variable with yaml, and return it.
    '''
    # Validate filename to prevent path traversal
    if not os.path.isabs(filename):
        # Check if the filename is within the allowed directory
        allowed_dir = os.path.abspath(os.getcwd())
        if os.path.commonprefix([filename, allowed_dir]) == allowed_dir:
            with open(filename, 'r') as f:
                return yaml.safe_load(f)
    else:
        # Handle absolute paths securely
